export const getWebhook = async (
  webhookId: string
): Promise<Result<WebhookWithoutSecret, ApiErrorResponseV2>> => {
  try {
    const webhook = await prisma.webhook.findUnique({
      where: {
        id: webhookId,
      },
      omit: {
        secret: true,
      },
    });

    if (!webhook) {
      return err({
        type: "not_found",
        details: [{ field: "webhook", issue: "not found" }],
      });
    }

    return ok(webhook);
  } catch (error) {
    return err({
      type: "internal_server_error",
      details: [
        { field: "webhook", issue: error instanceof Error ? error.message : "Unknown error occurred" },
      ],
    });
  }
};

// Internal-only — returns the signing secret. Never expose the result through an API response.

export const createWebhook = async (
  workspaceId: string,
  webhookInput: TWebhookInput,
  secret?: string
): Promise<Webhook> => {
  await validateWebhookUrl(webhookInput.url);

  try {
    if (isDiscordWebhook(webhookInput.url)) {
      throw new UnknownError("Discord webhooks are currently not supported.");
    }

    const signingSecret = secret ?? generateWebhookSecret();

    const webhook = await prisma.webhook.create({
      data: {
        ...webhookInput,
        surveyIds: webhookInput.surveyIds || [],
        secret: signingSecret,
        workspace: {
          connect: {
            id: workspaceId,
          },
        },
      },
    });

    return webhook;
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }

    if (!(error instanceof InvalidInputError)) {
      throw new DatabaseError(`Database error when creating webhook for workspace ${workspaceId}`);
    }

    throw error;
  }
};

