const onDuplicateWebhook = async () => {
  setIsDuplicatingWebhook(true);
  try {
    const response = await fetch(`/api/v3/webhooks/${webhook.id}/duplicate`, {
      method: "POST",
    });

    if (!response.ok) {
      const error = await parseV3ApiError(response);
      toast.error(error.message);
      return;
    }

    setOpen(false);
    router.refresh();
    toast.success(t("workspace.integrations.webhooks.webhook_duplicate_successfully"));
  } catch (err) {
    toast.error(err instanceof Error ? err.message : "Unknown error occurred");
  } finally {
    setIsDuplicatingWebhook(false);
  }

